import {createM26Id} from '../platform/id.js';
export function validateAppointmentDraft(draft={}){ const errors=[]; for(const key of ['clientId','startAt','endAt','modality']) if(!draft[key]) errors.push(key); if(draft.startAt&&draft.endAt&&new Date(draft.endAt)<=new Date(draft.startAt)) errors.push('endAt'); return {ok:!errors.length,errors}; }
export function buildAppointmentCommand(draft,revision=0){ const v=validateAppointmentDraft(draft); if(!v.ok) throw new Error(`M26_APPOINTMENT_INVALID:${v.errors.join(',')}`); return {type:draft.id?'CITA_REPROGRAMAR':'CITA_CREAR',entityType:'appointment',entityId:draft.id||createM26Id(),clientId:draft.clientId,baseRevision:revision,reason:draft.id?(draft.reason||'Reprogramación solicitada'):null,payload:{appointment:structuredClone(draft)}}; }
export function buildCancelAppointmentCommand({clientId,appointmentId,reason},revision=0){ if(!clientId||!appointmentId||!reason) throw new Error('M26_APPOINTMENT_CANCEL_CONTEXT_REQUIRED'); return {type:'CITA_CANCELAR',entityType:'appointment',entityId:appointmentId,clientId,baseRevision:revision,reason,payload:{patch:{cancellationReason:reason}}}; }
